sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    /*
    This script will insert a record in HSBC Outbound Symphony Message Logs
    when there is insert or update on the HSBC Symphony Message Log [MSSOTIQUBE-201]

	Unit Testing done and Review as part of MSSOTIQUBE-1097.
    */
    var body = current.message_body.getDisplayValue();

    try {

        if (current.servicenow_task_id != '' && body != '' && current.send_to != '' && current.servicenow_template_name != '') {
            var sym = new GlideRecord('x_hsb11_mss_sw_hsbc_outbound_symphony_message_log');
            sym.initialize();
            sym.servicenow_task_id = current.servicenow_task_id;
            sym.message_body = body;
            sym.sendto = current.send_to;
            sym.servicenow_template_name = current.servicenow_template_name;
            sym.type = current.type;
			sym.encrypted_message_id = current.encrypted_message_id;
            sym.state = 'Ready to be sent';
            sym.active = true;
			sym.source = 'Equities';
            sym.insert();
        }
    } catch (err) {
        gs.info("Error captured from business rule - HSBC-Record on Symphony outbound table " + err.message);
    }

})(current, previous);
